<?php require_once 'includes/db.php';$profile=$pdo->query("SELECT * FROM profile LIMIT 1")->fetch();$skills=$pdo->query("SELECT * FROM skills ORDER BY sort_order,name")->fetchAll();$exp=$pdo->query("SELECT * FROM experience ORDER BY start_date DESC")->fetchAll();function e($v){return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>CV — K.O DIVINII</title><link rel="stylesheet" href="assets/css/style.css"></head><body><header class="nav"><a class="brand" href="index.php"><span class="brand-mark">K.</span>K.O <b>DIVINII</b></a><nav><a href="index.php">Home</a><a href="works.php">Works</a></nav></header><main class="inner-page"><span class="eyebrow">CURRICULUM VITAE</span><h1>K.O <em>DIVINII.</em></h1><h2><?=e($profile['headline']??'Creative Developer')?></h2><p style="max-width:650px;line-height:1.8;color:#aaa"><?=nl2br(e($profile['about']??''))?></p><p class="mono"><?=e($profile['email']??'')?> <?=e($profile['phone']??'')?> <?=e($profile['location']??'')?></p><h2 style="margin-top:60px">Experience</h2><?php foreach($exp as $x):?><div class="experience-row"><span class="mono"><?=e($x['start_date'])?> — <?=e($x['end_date']?:'PRESENT')?></span><div><h3><?=e($x['role'])?></h3><p><?=e($x['organization'])?></p></div><p><?=e($x['description'])?></p></div><?php endforeach;?><h2 style="margin-top:60px">Skills</h2><div class="skills-list"><?php foreach($skills as $s):?><div class="skill-row"><span class="mono"><?=e($s['name'])?></span><span class="skill-bar"><i style="width:<?=min(100,(int)$s['proficiency'])?>%"></i></span><span class="mono skill-level"><?=e($s['level']?:$s['proficiency'].'%')?></span></div><?php endforeach;?></div><p style="margin-top:50px"><button class="button button-light" onclick="window.print()">Print / Save as PDF ↗</button></p><p><a class="text-link" href="index.php">← Back to portfolio</a></p></main><style>@media print{body{background:white;color:#111}.nav,.text-link,button{display:none!important}.inner-page{padding:20px}.experience-row p,.inner-page p{color:#333}.mono{color:#555}}</style></body></html>